   "titulo": "La RDC supera la barrera de los 12.000 casos de ébola, incluidos más de 5.900 muertos",
   "resumen": "El brote de ébola que avanza rápidamente en el este del Congo ha superado los 12.000 casos confirmados, según datos gubernamentales, mientras los combates propician la propagación de la enfermedad.",
   "fuente": "DW Español",
   "url": "https://www.dw.com/es/la-rdc-supera-la-barrera-de-los-12-000-casos-de-ébola-incluidos-más-de-5-900-muertos/a-80057782?maca=spa-rss-sp-all-1122-xml-mrss",
